/**
 * 学习力训练方法库（来源：《学习力训练系统》四大板块 258 个方法）。
 * N=能力训练 D=动力激发 X=学法优化 P=品格养成。
 * 供 E3 学业诊断（V2.7 五维）报告生成针对性训练方案。
 */
export type TrainingMethod = {
  id: string;
  board: "N" | "D" | "X" | "P";
  /** 子板块，如 学习五大流程 / 微启动 */
  sub: string;
  name: string;
  /** 适用情况（学习问题描述） */
  problems: string;
  /** 训练目的 */
  purpose: string;
  /** 配套工具 */
  tool: string;
  /** 操作步骤（可落地执行） */
  steps: string[];
  /** 时间安排（频率+周期） */
  schedule: string;
};

export const BOARD_LABEL: Record<TrainingMethod["board"], string> = {
  N: "能力训练",
  D: "动力激发",
  X: "学法优化",
  P: "品格养成",
};

