    tool: "无",
    steps: ["留出5-10分钟的时间，确保一个人位于一个空间内，不受电话、家人、朋友的打扰。准备几枚葡萄干。按照8个步骤进行正念尝试。", "每个步骤维持20—30秒时间", "持", "拿起一枚葡萄干，将它放在手掌上或者用手捏住。将注意力放在葡萄干上，认真观察，就好像你以前从未见过这种东西一样。你是否能感受它在手掌中的重量，它是否在你的手掌中投下了小小的阴影。", "看", "花一点时间认真审视葡萄干。想象你从未见过这种水果。非常认真的、全神贯注地观看，让你的目光滑过它的每一个部分，审视每一个光亮部位，阴暗凹陷，褶皱和凸脊。", "触", "用手指翻转这枚葡萄干，探索它的纹理结构。将它放在另一只手的拇指和食指之间，现在感觉如何？", "嗅", "现在，将葡萄干放在鼻子下面闻一闻，每次吸气时有什么发现。它是否有某种气味。让这种气味充满你的意识。如果没有气味，或者气味很淡，也要如实注意。", "放", "慢慢将葡萄干放入口中，注意你的手掌和胳膊知道如何准确地实施这一动作。然后，慢慢放在嘴里，注意感受舌头接纳它的动作。不要咀嚼，仅仅品味它在舌头上引发的感觉。然后，用舌头缓缓感知它，持续30秒钟。", "嚼", "当你准备好以后，有意识地咬一口，感受葡萄干和口腔内的变化。注意体会它释放的任何味道。当牙齿咬入葡萄干时，注意感受它内部的组织状况。继续慢慢咀嚼，但暂时不要吞咽。注意口腔内的变化。", "咽", "当脑海中出现第一个吞咽念头时，你是否感觉得到。在真正吞咽前，要全神贯注地体会这个欲望。注意舌头为了吞咽做了哪些准备。观察你是否能跟踪感受吞下葡萄干的过程。如果可以，有意识地感受葡萄干慢慢落入胃部的过程。如果你没有一次吞下整个葡萄干，就要有意识地第二次、第三次感受吞咽过程，直到完全咽下那枚葡萄干。注意体会吞咽后舌头的动作。", "感", "最后，用一点儿时间感受吃完葡萄干后的影响。口腔中是否还有余味，没有了葡萄干，口腔的感受如何，是否有自动拿起另外一枚的倾向。"],
