    steps: ["将一周分为三部分 ：7=5+1+1", "周一到周五：狂学", "在保证睡眠的基础上，把时间掰成两份，上课与不上课。在这五天，你需要最大化利用不上课的时间。从寝室到教室路上可以选择背一首古诗；下课时间复习课堂内容，整理笔记；自习课完成作业；晚上睡前总结复习一天的内容。总之除了睡觉吃饭，最大程度的利用时间进行学习，进入疯狂专注模式。", "周五晚＋周六白天：狂欢", "这段时间是属于你自己的，你可以在家里睡一天来奖励你一周的勤奋，也可以约三五同学出去逛街吃饭，还可以抱着零食在家里看一部你喜欢的剧或电影。当你有了对周六狂欢的期待，你就会在周一到周五表现的更好。", "周六晚+周日：周末作业+复盘", "开始恢复正常作息，做完作业后，拿一张纸，认真的记录一下你的一周所学内容、时间利用情况、一周的专注程度。当你看着满满当当的内容时，你会有很强的满足感，以及对未来继续奋斗的决心。", "如果做完作业和复盘后还有剩余时间，不要做令自己停不下来的事，比如看剧玩手机，你可以退而求其次读读自己喜欢的书，画自己喜欢的画，让自己为回归到周一的战斗状态做淮备。", "即时奖励", "坚持一个月后，给自己一份奖励，可以是一杯奶茶，也可以是一顿火锅，还可以是你喜欢了很久的一件衣服。总之，你所设置的奖励要和你的努力程度及坚持程度成正比。"],
