    tool: "无（如有必要可研发相关笔记本）",
    steps: ["记录期——觉察毅力基准线（第1周）", "每天记录自己做了什么，除了学习，其他的事情也需要记录下来。第七天晚上，算一下平均每天有效的学习时间。", "注意，有效学习时间指的是剔除上课、走神、学习中途玩的时间。", "格式参考：19:00-20:00 看生物书（走神了10分钟，玩了13分钟手机）", "抗拒期——逐步增加学习有效时间（第2-4周））", "每周都增加一点有效学习时间，建议每天增加半小时。比如现在的基准线是每天2小时，那么第一周目标，就是每天2.5小时。第二周是每天3小时，以此类推。", "注：", "（1）不看成绩，只看有效学习时间。", "（2）不要贪多，不要觉得每天才多半小时，这个目标太低。", "（3）不要超标，比如这周目标是，每天2.5小时，那么就算今天状态很好，也不能让有效学习超过3小时。", "不稳定期——保持有效时间的持续（第5-7周）", "自己设计好3个规则保持有效时间的持续。", "（1）行为规则", "根据前几周执行学习任务的经验，总结哪些任务是完成时间相对比较固定的，现在就可以把这些任务完成时间固定下来，成为行为规则。", "比如：固定大课间休息时间，一定用来背英语和语文学科相关内容；晚自习结束前一定是检查总结今天所有科目的作业错题情况；睡前在床上，一定是背诵副科知识点。具体情况可以按照平时的作息、学习的内容，变成适合自己的版本。", "（2）例外规则", "例外规则要解决的是，如果今天没有达成时间目标应该怎么办。例外规则主要包含两点：① 确定最低有效学习时间。比如现在每天需要坚持的有效学习时间是3小时，那么底线就是今天至少2小时。②思考如果最低有效学习时间都没达到，应如何补救，确定补救措施。比如晚上少睡一点，补上时间，比如明天的有些副科不太重要，可以拿来自习补上今天缺少的时间。或者将缺失的时长记录下来，周末再补上。", "（3）奖励规则", "当每周都完成了有效学习时间目标，可以奖励自己周末干点自己喜欢的事情，例如玩手机，或者给自己买个喜欢的文具等等。奖励规则可以根据实际情况自定。需要注意的是，这个奖励规则是暂时的，只适用于不稳定期。", "稳定期——制定成绩目标（第8-9周）", "制定成绩目标，赶超他人，获得学习中的成就感与自豪感。"],
