    purpose: "1.提升学生的学习动力，健全学生的学习价值观；\n2.改善学习给学生带来的情绪体验，使学生感受到学习的乐趣；\n3.提升学生的自我效能感；\n4.提高学生对学习的兴趣，从外部动机转换为内部动机，从而有效提升学生的学习主动性。",
    tool: "代币",
    steps: ["确定矫正目标", "（1）了解学生优点；", "（2）确定学生需要矫正的行为。", "准备阶段", "（1）加强沟通、树立信心", "沟通理解是实验开展的前提。矫正活动开始之前，需要和学生做深度的交流，讲明了目的与要求，营造出一种积极的氛围，得到了他们的理解和认同。", "（2）激发兴趣、选择强化物", "发放意见调查表，让学生们填写自己喜欢得到的奖励，通过深入调查，了解每个学生最喜欢的东西，然后整理意见，并召开班会确定大家都乐意接受的东西作为强化物，可以是精神奖励。据同学们喜欢的程度不同，换取这些东西所需要的代币也不同，有一定的层次性，根据学生的实际情况，把物质的东西和精神的奖励结合起来。", "（3）拟定代币", "用分数来记录，班主任安排记录，同学互相监督，学科教师检查，代币的数量由班主任，学科教师、学生共同认定，并保证代币只能在拟定的交换系统中使用，除此之外没有别的用途。", "实施阶段", "（1）前两周：学生自己记录自己的课堂表现，然后把自己的记录填在教室后面张贴的记录表上供老师、同学监督。根据学生的记录，确定小组和班级获得的代币，据此作为是否获得强化物的依据。", "注意事项：①活动的过程中，教师加强认知识辅导，特别是问题较多的学生，通过谈话交流和榜样的力量，让同学们产生强大的想要纠正自己不良行为的动机。②每天进行总结评价，班主任对好的表现加以肯定和鼓励。③代币兑换一周3次。④教师在总结的过程中强调精神奖励，引导学生获得精神上的满足，有助于将学生的外在学习动机转化为内部学习动机。", "（2）第三、四周：在第一阶段的基础上提高要求，并且在这个阶段更加注重对个别课堂干扰行为多的学生的心理辅导，让他们愿意、乐意、并且努力纠正自己的行为。兑换代币也由之前的一周三次改成一周两次。", "（3）第五、六周：再次提高要求。在这一阶段一周兑换代币一次。"],
