    purpose: "通过德韦克的成长型思维培养四步走，培养学生的成长型思维，帮助学生在学习过程中调解自我情绪，营造更多积极的学习体验，提高学生的抗逆力、自我认知能力。",
    tool: "成长思维本",
    steps: ["接受", "固定型思维是我们以固定的思维模式考虑问题，往往觉得自己的能力是固定的，自己没办法做什么什么。其实接纳固定型思维往往是我们解决问题的第一步。大方承认没有人是完美的，接受自己的不完美，这样才能放松自己的心态，追求更多的美好。", "具体操作：具体可主持一场微班会，让学生了解各种各样固定型思维的表现，然后再向学生传递正确的认知，这样的表现是正常的，每个人都会有，不同的是，不同的人选择不同的方式去应对固定型思维。", "观察", "清楚是什么事件激发了自己的固定型思维模式，它在什么场合下出现了。比如说在面对困难的时候吗？固定型思维出现说：“放弃吧，你没有那么大能力。”当这样的固定型思维跳出来的时候，首先要搞清楚引起它出现的事件是什么。", "具体操作：学生可以每天对自己一天的事情进行复盘，思考今天学习过程中我是否出现了固定思维，它是由什么事情引起的，必要情况甚至可以将自己的固定型思维表现以及引起该思维的事件记录下来。", "命名", "当你的固定型思维出现了，给固定型思维起个名字，名字没有限制，只要你喜欢就行。起名最重要的好处就是让你意识到你有这样一种思维模式存在。当它出现的时候，你可以启动大脑的反射机制，与它进行对话，从而找出这种思维的很多想法的漏洞。", "具体操作：当学生复盘后，明确了自己在什么情况下出现了什么样的固定型思维，然后依照自己的喜好给固定思维取个名字。", "教育", "教育就是当固定型思维出现的时候，你可以耐心地说服“他”改过自新，改变他的心态和行为。比如说你的固定型思维命名为“小黑”，那面对困难就可以这样教育他：还没有尽力呢，方法也没多尝试呢？怎么就知道自己不行了？试试吧。", "具体操作：当学生给固定型思维取了名字后，与他进行对话，甚至可以写下来。内容包括鼓励固定型思维改变，鼓励固定型思维挑战自我，给固定型思维增加信心，让其跳出舒适圈。"],
