    tool: "无",
    steps: ["以慢跑作为室外核心运动方式。 平均来讲，每天1000~2000米的慢跑运动比较适合中学生，身体较弱者可以从400米、800米起步，然后逐渐增加到2000米。", "以跳绳、深蹲、平板支撑等作为室内核心运动方式。 在慢跑之外，还必须有几项室内运动以供选择，否则碰到雨雪天气就有可能被迫中断运动。", "以各类拉伸运动和头肩部活动作为课间锻炼方式。 中学生久坐、蜷缩、低头造成了颈椎、肩膀、腰背的僵硬和下肢血液流通不畅，这些运动能够解决这些问题。", "以兴趣爱好类运动作为灵活补充。 篮球、足球、羽毛球等多种体育运动，都可以选择。", "温馨提示：", "初次锻炼强度不宜过大，应循序渐进，科学锻炼，每天坚持。", "做好锻炼前场地、器材的检查，以确保锻炼时的安全。", "体育锻炼要结合场地条件和身体情况合理选择运动项目。", "运动前进行热身活动，防止受伤。运动后进行放松及保暖，切忌立即坐下或躺下。", "不要空腹运动，但也不应大量进食。运动时以少量多次原则适当补充水分，切忌大量饮水。", "要穿合适的运动服、运动鞋进行锻炼。"],
    schedule: "使用频率：每周3~5次，每次20~30分钟；使用周期：1个月",
