    steps: ["尝试并找到自己适合与喜欢的运动项目。运动项目的选择不需要局限于跑步、跳绳等常规运动，还可以选择乒乓球、羽毛球、踢毽子、运动操、俯卧撑、高抬腿等。尽量选择可以毫不费力进入状态，自己喜欢，和比较容易坚持的；", "设立运动目标。设立目标需要遵循smart原则（具体、可测量、可达到、相关性、时间要求），对于没有运动习惯的学生，一开始可以设立非常简单的目标，比如一天运动5分钟，之后根据耐受度逐渐增加运动时间。并且可以多种运动项目交叉。建议多利用碎片时间，比如大课间时可以做高抬腿1分钟，午间休息前可以跑步5分钟，睡觉前可以做俯卧撑2分钟；", "建立运动反馈机制。运动初期还未养成习惯时，可以给自己设定完成周目标/月目标的奖励，以此激励自己；", "寻找运动伙伴。最好找到一个也想要运动的朋友、家人或同学，约定一起运动、互相监督。", "温馨提示：", "初次锻炼强度不宜过大，应循序渐进，科学锻炼，每天坚持。", "做好锻炼前场地、器材的检查，以确保锻炼时的安全。", "体育锻炼要结合场地条件和身体情况合理选择运动项目。", "运动前进行热身活动，防止受伤。运动后进行放松及保暖，切忌立即坐下或躺下。", "不要空腹运动，但也不应大量进食。运动时以少量多次原则适当补充水分，切忌大量饮水。", "要穿合适的运动服、运动鞋进行锻炼。"],
