    problems: "记不住知识，一看到大段文字就头晕；",
    purpose: "增加学生的记忆技巧，减少知识的遗忘。",
    tool: "无",
    steps: ["将记忆的资料转换为具体的图像，转换得越清晰，越生动越好。比如：石榴，具体的图像可以为又红又大的石榴；鞋子，具体图像为闪闪发光的水晶鞋子。图像转换得越生动、越形象，越能更强的刺激大脑，记忆起来越容易；", "将各种图像链接。建立链接的时候，链接的部分越夸张，越反逻辑越好。比如：上面的石榴和鞋子，可以链接为：又红又大的石榴里，塞满了亮晶晶的水晶鞋；", "回想记忆。链接建立后，为了记忆得更牢固，更准确，必须对所有链接的资料按照步骤2重新回忆一遍。"],
