    purpose: "增加学生的记忆技巧，增强对知识的深层理解，预防“不懂装懂”的问题，减少知识的遗忘。",
    tool: "无",
    steps: ["确定主题并开始学习。", "需要选择一个学习的内容，可以是书本上的概念，可以是试卷上的一道题，只要是你想掌握的知识。然后先阅读浏览，对他大致有一个印象。这个过程一定要快速，不要过于纠结。然后在一张白纸上凭你的印象将这个知识概括性的写出来，最后是关键的观点信息和过程信息。", "试图向其他人教授你所学。", "可以在脑海中假设有一个人，你要将这个知识点教给他，可以用你自己的语言叙述，但是一定要试着准确详细的给脑海中的人讲明白。当然，如果你身边有你的朋友，可以让他配合你5分钟，试着给他讲一讲。", "在卡住时重新去查验教材。", "回顾你刚才讲授的过程中，自己不明白的讲不清楚的地方，扩展性的补充和了解。这个时候，你应该会对这个问题有一个比较深入的理解。", "简化并整理结构。", "通过第二步纠正了你的错误发现了不足，现在可以再用自己的语言简化你的解释并使它更好。还可以随时返回第2步和第3步，直到你对主题有了清晰的了解。"],
