    purpose: "多用于数学科目，解决不知如何解答大题或者因看漏条件导致结果出错的问题，促进学生自我反省而提高问题解决的能力",
    tool: "无",
    steps: ["在审题到解题过程中对每个步骤进行自我提问。提问步骤如下：", "理解问题阶段问：", "-未知条件是什么？", "-已知条件是什么？", "-已知条件足以确定未知量吗？", "-多余还是不足？", "拟定计划阶段问：", "-过去见过这种题吗？", "-若见过是否它以稍许不同的方式出现？", "-我能应用一个具有相同或相似未知条件的熟悉问题解答当前题吗？", "-如果不能解答当前题应问：我能从已知条件中产生什么有用的东西？", "-使用了所有的条件和数据了吗？", "执行计划阶段问：", "-能清楚地认定每一步都是对的吗?", "-能证明它是对的吗？", "回顾步骤问：", "-我能检验结果的正确性吗？", "-我能检验推理过程吗？", "-我能运用这个结果或方法于其它问题吗？", "注意提问尽量在平时练习和作业的过程中熟练应用，成为习惯后，考试中会自动化的进行问题确认，不会消耗过多时间。"],
