    name: "X四步习惯法",
    problems: "1.学习习惯不好，不能坚持每天记单词、复习、按时完成作业等习惯；\n2.想要养成提高学习效率的习惯，如每天运动、按时睡觉、每天背单词作文素材，但是没有方法，很难坚持。",
    purpose: "提供养成习惯的方法和技巧，使学生能够更好坚持，养成自律学习的习惯。",
    tool: "无",
    steps: ["首先选择一个自己很想养成的学习习惯，比如：每天背单词、每天进行体育锻炼、每天复习当日的学习内容。然后按照以下四步，行动起来，只要每一步都能完成，习惯养成会非常轻松。", "设置行动提示", "通过创造环境提示，形成心理暗示。将能够向我们提示期望养成的习惯的东西，放在最显眼的位置，不断提醒自己，促使自己去行动。", "比如习惯目标是每天背单词，那么你可以在卧室、厕所、课桌、寝室里贴上一些写满单词的便签纸，让背单词可以随时随地进行。", "增加行动的吸引力", "将喜好的高频动作与需要做的低频习惯搭配在一起，利用高频行为强化低频行为。", "比如在第一步时你已经将便签纸贴在了卫生间的镜子上，那么当你每天早晨刷牙之后，立马背几个单词。原本“背单词”这个低频行为就会和“刷牙”这个高频行为练习起来，之后只要已进行刷牙的动作，你就会想起背单词。", "让习惯简便易行", "将行动变得简单，比如每天看1h书很难，就从每天5分钟开始。每天背20个单词很难，一开始就只设置5个，随着习惯的养成和自身承受力增加，再增加单词数量。", "建议：两分钟规则。“当开始培养一种新习惯时，它所用时间不应超过两分钟。”", "给习惯设置奖励", "行动完成后，是否能获得及时奖励或享受到乐趣。从一项行动中越快享受到乐趣，你就越容易重复这项行动。", "比如可以设置简单的打卡环节，在计划本上写上每天要做的事，完成后就打上勾或者划掉，这种确认的环节会让你成就感慢慢，立马获得快乐。", "注：如若没有主观的收获，则建议设置客观的奖励。比如物质奖励。"],
    schedule: "使用频率：随时；使用周期：无",
