    problems: "1、学生记忆知识死记硬背，记忆效果不佳；\n2、缺乏科学记忆方法，容易遗忘学过的知识内容；\n3、知识记忆散乱，没有形成知识之间的链接与框架。",
    purpose: "1.多元组合是在积极思考、达到深刻理解的基础上，将新知识与旧知识进行联结，从而达到记忆效果的方法，能够帮助学生加深知识的理解与记忆，并形成知识体系。\n2.对工作记忆能力不强者，有很好的改善记忆功能，并且一定程度上促进思维能力的提升以及信息加工策略的多维度发展。",
