    purpose: "1、通过严格把控各项任务的学习时间，可以有效帮助学生改善记忆效果，提高学习效率，规律作息习惯。\n2、一定程度上帮助学生提高工作记忆、时间管理、行为管理能力。",
    tool: "无",
    steps: ["上午记忆时间段", ": 00-7:30：最适合记忆的时间，可以背诵语文或英语，或者进行早读，加深记忆。", ": 30-8: 00：早餐时间，吃早饭，同时可以利用耳朵听英语听力或者时事新闻。", ": 00-9: 00：一天中耐力最好的时候，可以安排理科类的复习，这个时间段最好多进行思考。", ": 00-11: 00：这个时间段短期记忆力比较好，对于即将要参与考核的东西可以进行突击，可达到事半功倍的效果。", ": 00-12:00：这个时间段大脑和身体都比较疲惫，可以做一些常规的练习题进行复习，达到巩固的目的。", "中午休息时间段", ": 00-12: 30：午饭时间，吃饭的时候可以听一些放松的音乐，使身心更愉悦。", ": 30-12: 50：午饭后不宜直接睡觉，可以站立一会，看看窗外的景色，既有助于消化，也能让眼睛放松。", ": 00-14: 00：午睡的时间，中午是承上启下的时间，劳累一上午需要休息一下，下午才会更有精神。", "下午思考时间段", ": 00-16: 00：这段时间是大脑高速运转的时候，可以做一些头脑风暴，需要思考的问题放到这个时间段。", ": 00-18: 00：这个时间段适合做一些计算和费劲的功课。", ": 00-18: 30：晚饭时间，这个时候可以和同学或朋友坐在一起聊聊天，缓解一下高度紧张的心情，迎接晚上的学习。", ": 30-19: 00：休息一会，做些自己比较感兴趣的事情，放松一下心情，为自己充充电。", "晚上复习时间段", ": 00-19: 30：适当的做做运动，但是不要做很大强度的运动了，有好的身体才能更好的学习。", ": 30-22:00：根据自身情况安排复习，可以交叉安排复习课目。", ": 00-22:40：回顾一天所学，可静坐或是躺在床上在脑子里大致回顾当天所学的知识，并制定第二天的学习计划。", ": 40-23: 00", "准备睡觉，睡前喝一杯热牛奶，对于睡眠有很好的帮助哦，尽量不要熬夜。", "注：1、早上刚起来的一段时间和刚吃饱的一段时间定要利用好，因为这段时间注意力比较容易集中；早饭一定要吃，不然一天都没有精神。", "一定要午睡，但是要把握好午睡的时间，不睡下午没精神，睡的多了依旧没精神；午饭后要休息一会再睡觉， 不然肠胃会不舒服。", "下午这个时间段比较适合思考，可以安排一些需要计算和逻辑性强的学科；也要注意休息哦! !劳逸结合才是科学的。", "晚上这个时间段比较适合复习，忙碌了一天，大脑也需要休息，所以不要再做高强度的工作了；一定要合理安排睡觉时间，熬夜是最错的了。"],
