    purpose: "1、通过思维导图的方式让学生对知识结构形成体系，以及让学习笔记更加清晰明确，方便记忆。\n2、通过图像呈现的方式，增加趣味性，帮助学生激发学习兴趣；通过整理框架提升学生的逻辑思维能力以及工作记忆能力。",
    tool: "a4纸、彩笔",
