    purpose: "1、通过归纳对比让学生对知识的理解更为清晰透彻，能够追本溯源，明晓联系，使知识在脑中更有印象。\n2、帮助学生加强组织策略以及逻辑思维的运用。",
    tool: "表格",
    steps: ["归纳比较", "①纵向归纳。从时间顺序上，对知识点进行纵向的梳理和归纳，然后逐一比较其共同点和不同点，可以使用列表形式。比如，以历史学习来说，“中国土地制度”，可按时序，一个朝代一个朝代地逐一清理，理出一条线后，就能看清我国土地制度的来龙去脉，掌握其沿革情况。同时进行比较，梳理每个朝代土地制度的变化过程", "②横向归纳。从空间顺序上，对知识点进行横向的梳理和归纳，然后逐一比较其异同，也可使用列表形式。在相同或不同的时间里，将不同空间相同或相似的知识点排列在一起，这样梳理过后再比较其异同效果颇佳。比如拿日本资产阶级革命和中国资产阶级革命两相比较。", "学生就对比内容进行思考、反馈并整理笔记，及时复习，这样可以使学生在操作过程中收获更有条理、逻辑的学习效果。"],
    schedule: "使用频率：一周或一月；使用周期：无",
