    name: "X归纳整理",
    problems: "1、学生在学习过程中被动学习，只完成老师布置的任务，知识点学习不够透彻、深入；\n2、知识记忆散乱，没有形成知识之间的链接与框架；\n3、知识学习单薄，举一反三，应用困难。",
    purpose: "1、通过主动整理知识点，激发学生学习主动性和积极性，从而获得较高的学习体验，提升学习成就感，并且使其对知识的理解更为透彻，能够举一反三，提高学业成绩。\n2、帮助学生提升逻辑思维能力、学习监控以及学习优化能力、使其学习更有条理性，不慌乱。",
    tool: "笔记本",
    steps: ["对知识点进行整体阅读和学习，形成一个基本了解和整体认识。", "归纳整理前，明确要通过这种方式解决关于这个知识点的什么问题以及明确整理的维度（从什么角度进行整理）。", "确定整理任务，收集相关资料，并根据资料进行整理。（在具体进行整理的时候，若遇到整理难点可求助老师或同学）", "归纳整理完成后，可以将结果进行再次梳理简化，使用关键词，将关键词用自己的语言串联理解，以及在笔记上书写自己的理解、观点，甚至关联相应的案例，从而整理成方便对该知识进行记忆以及应用巩固的模式。", "整理过程中以及完成后问自己这3个问题：①是否带着充分思考在整理；②整理完成后的状态和收获；③整理后是否清晰如何记忆和应用。从而不断协助改进整理。", "注：可以设置专门的归纳笔记本，也即整个笔记本都是整理型的知识，也就是二次加工的、三次加工的知识。"],
    schedule: "使用频率：学完单元课程后；使用周期：无",
