    steps: ["拆析你想要学习的知识和技能", "明确你真正想学习的内容，并将知识内容进行拆分，抓住重要部分进行学习。（很多我们想学的知识，其实是很多零散部分的集合，每一个部分都有自己的要求。如果能想明白这些零散部分，哪些能帮助自己达到目标，就可以先学习这部分。如果你能先学会这些最重要的东西，你就能在最短的时间提升自己的表现。）", "学到足以自我纠正则开始实践", "借助资源学习一定的理论知识，比如书籍、权威资料等，期间不断进行理解的调整，到可以纠正自己的错误就可以开始实践。比如想学编程，不要给自己买20本书然后告诉自己“等我读完这20本书就开始编程”。不要让自己背负上一摞书的包袱，最开始只要学到你能够自主练习并达到自我纠正的程度就可以进行实践了。", "排除一切干扰", "学习时全神贯注，确保学习过程不被轻易打断。期间不要沾染电脑、手机、电视、QQ、微信、游戏等APP或设备。", "学习时间至少累积20个小时", "学习任何的时候都会有一个瓶颈期，在没有学到一定程度之前，你可能不会有任何突破，但是一旦你过了这个瓶颈期,一切就变得简单起来了。所以最少坚持练习20小时，投入最大的时间和精力，可以每天只花费45分钟，坚持一个月，就能达到一定效果。"],
