    purpose: "通过不断进行回忆的方式，温故而知新，促进学生对知识的记忆和理解，以及对错题的整理改进，对应试技巧的运用，从而提升学业成绩；\n帮助学生培养良好的学习习惯，提高反思能力以及学习优化能力。",
    tool: "复盘笔记本",
    steps: ["一、日复盘", "日复盘的核心是睡前对每天所学的内容进行复习。", "躺到床上，闭上眼睛，但不直接睡觉，回忆一下白天所学的内容，就像在大脑里面放电影一样，重点回忆一些重要的概念、公式、定理等。", "如果记不起来，就先睡觉，第二天起床再去翻书，重新记忆。", "二、周复盘", "周复盘的核心是梳理知识之间的联系，建立知识框架。由于每天学到的东西都是散乱的知识点，比较孤立，也难以理解，经过一周的学习，能积累不少的知识，这时就需要去梳理知识间的联系，以便更好地理解知识。", "在周五晚上或者周六早上进行周复盘，拿出笔记本，对这周的学习内容归纳整理，建议画思维导图，如果是文科，可以写上关键词，如果是理科，可以写上公式。", "如果整理完发现还有很多不会的内容，赶紧靠周末补回来，重新学习。", "三、月复盘", "月复盘的核心是总结做题技巧，轻松应对月考。初中开始基本每个月就会考一次试，所以要在月考前进行复盘,才能在考试中游刃有余。", "先看课堂笔记以及每周做的复盘笔记，整体过―遍这个月的学习内容。", "刷题，可以刷书本的课后习题，也可以找真题去刷。", "整理错题,把做错的题目整理进错题本，并及时去查漏补缺。", "归纳各类题型，并提炼做题技巧，这样下次遇到相似题目就能举—反三。", "复习错题,重新做一遍这个月收集的错题，看还有哪里不会，及时学习。"],
