    tool: "任务清单",
    steps: ["罗列任务清单", "罗列要完成的任务，将其列入任务清单。这些任务可以是常规学习任务，比如老师布置的作业，要求的预习、复习任务等，也可以是个人特别的任务，比如根据自身薄弱知识点增加的附加任务。尽可能详细地列出任务，以便更好地跟进和监控。", "评估任务优先级", "对任务进行评估，确定它们的优先级。这可以根据任务的重要性、紧急程度和时间限制来评估。把事情分为重要紧急、重要不紧急、紧急不重要、不重要不紧急的类别，先完成重要紧急的任务、其次是重要不紧急以及紧急不重要的任务、最后完成不重要不紧急的任务。将任务分为根据任务的优先级，安排时间和资源，确保能够按时完成任务。", "安排任务时间表", "根据任务清单和任务优先级，制定任务时间表。时间表应该包括任务的开始和结束时间。时间表应该根据自己的能力来安排，时间计划可以适当放宽，确保能够完成任务。", "监控任务进度", "在开始任务后，需要及时监控任务的进程，及时更新任务进度。减少被无关因素影响，确保任务能够按时完成。", "完成任务", "一旦任务完成，及时对过程进行总结和反思，以便更好地改进和优化未来的清单计划。"],
